#!/usr/bin/env bash
# matmul-stft: re-export every final rung-C student with the pad-free MatMul front end (same weights), judge and time it
cd "$(dirname "$0")"
echo "##### deployed yamnet_large_general, prefix timing"
CUDA_VISIBLE_DEVICES='' $(bash tools/python_path.sh) 05_distill/prefix_bench.py cut /home/luke/projects/buzzdetect/engine/models/yamnet_large_general/model.onnx --out /home/luke/projects/buzzdetect-training/05_distill/data/_shared/arch_mm/_prefix_yamnet 2>&1 | tail -3
/home/luke/projects/buzzdetect/engine/.venv/bin/python3 05_distill/prefix_bench.py time /home/luke/projects/buzzdetect/engine/models/yamnet_large_general/model.onnx --out /home/luke/projects/buzzdetect-training/05_distill/data/_shared/arch_mm/_prefix_yamnet 2>&1 | grep -v "^20[0-9][0-9]-\|arning\|Removing"
